"""--- GoalWrite a Python program that prints the relative frequence of each letterof the alphabet (without distinguishing between lower and upper case) in thebook.--- Specifications- the program should have a --help option summarizing the usage- the program should accept the path to the input file from the command line- the program should print out the total elapsed time- the program should have an option to display a histogram of the frequences- [optional] the program should have an option to skip the parts of the text  that do not pertain to the book (e.g., preamble and license)- [optional] the program should have an option to print out the basic book  stats (e.g., number of characters, number of words, number of lines, etc.)  """with open('The republic by Plato.txt', 'r', encoding='utf-8') as file:    book = file.read() def letter_counter(lowercase_letter, uppercase_letter):    counter = 0    for character in book:        if character == lowercase_letter or character == uppercase_letter:            counter += 1    return counterdef print_counter(lowercase_letter, uppercase_letter):    print(        f"Letter {lowercase_letter} appears "        f"{letter_counter(lowercase_letter, uppercase_letter)} times"        )        lowercase_string = 'abcdefghijklmnopqrstuvwxyz'for letter in lowercase_string:    print_counter(letter, letter.upper())